sub actual_getAllRules {
	my $c = shift;
	my @ret = ();
	# Actual code for extracting getAllRules
	$cdb  = esmith::ConfigDB->open();
	$adb = esmith::AccountsDB->open();
	$pdb = esmith::ConfigDB->open('processmail') or die "Could not open processmail DB\n";
	my $PanelUser = $c->get_panel_user();
    my @rules = $pdb->get_all_by_prop(type => "$PanelUser");
    return $c->l("NO_RULES") if (@rules == 0);
    foreach my $rule (@rules)
    {
        my $key        = $rule->key;
        my $basis      = $rule->prop("basis")     || '';
        my $basis2     = $rule->prop("basis2")    || '';
        my $deliver    = $rule->prop("deliver")   || '';
        my $deliver2   = $rule->prop("deliver2")  || '';
        my $action     = $rule->prop("action")    || '';
        my $action2    = $rule->prop("action2")   || '';
        my $folder    = ("$action" eq "sort" )? $deliver  : '';
		$folder = "INBOX" if "$folder" eq "" && "$action" eq "sort";
        my $copy       = $rule->prop("copy")      || '';
        my $oldpmRule  = '';

        for ($basis, $basis2)
        {
         if ($_ eq '<')
         { $_ =  'sizelt'; }
         elsif ($_ eq '>')
         { $_ =  'sizegt'; }
        }

        my $b1    = $c->l($basis);
        my $b2    = $c->l($basis2);
        
        my $copyto     = $rule->prop("deliver2")  || '';# useless
        if (($copy eq 'yes') && ($action2 eq 'inbox'))
        { $deliver2 = "";  $copyto = 'inbox'; } # copyto is useless

        $deliver = GetDisplayName($deliver);
        $deliver2 = GetDisplayName($deliver2);
        
        $key = $rule->key;
	
        push @data,
            {
              key        => $key,
              basis      => $basis,
              basis2     => $basis2,
              criterion  => $rule->prop("criterion")  || '',
              criterion2 => $rule->prop("criterion2") || '',
              deliver    => $deliver,
              deliver2   => $deliver2,
              folder    => $folder,
              action     => $action,
              action2    => $action2,
              copy       => $copy,
              Modify     => "<a href=mailsortingd?trt=RULES&account=$PanelUser&Selected=$key>".$c->l('MODIFY')."</a>",
              Remove     => "<a href=mailsortingd?trt=REMOVE&account=$PanelUser&Selected=$key>".$c->l('REMOVE')."</a>",
              b1         => $b1,
              b2         => $b2,
              a          => $a,
              b          => $b,
              c          => $c,
            }
    }
	return @data;
}

sub get_getAllRules {
    # Return an array of hashes of the contents for each row and column for getAllRules
	my $c = shift;
	

    my @source_records = $c->actual_getAllRules();
    my @transformed_records;
    my %Field_Mapping = getAllRules_FIELD_MAPPING();
    # Iterate over each record in the source array
    for my $source_record (@source_records) {
        my %transformed_record;
        # Iterate over each key-value pair in the $Field_Mapping constant
        while (my ($target, $source) = each %Field_Mapping) {
            # Check if the source field exists in the source record
            if (exists $source_record->{$source}) {
                # Assign the source field value to the target field in the transformed record
                $transformed_record{$target} = $source_record->{$source};
            }
        }
        # Add transformed record to the array if it's not empty
        push @transformed_records, \%transformed_record if %transformed_record;
    }
    return \@transformed_records;
}



