sub get_full_name{
	my $c = shift;
	my $adb = esmith::AccountsDB->open();
	my $PanelUser = $c->get_panel_user();
    return  $adb->get_prop($PanelUser, "FirstName") . " " .
            $adb->get_prop($PanelUser, "LastName");
}

sub GetDisplayName {
    my ($s) = @_;
    $s =~ s/(.*)//;   # untaint the input
    my $decoded = decode('IMAP-UTF-7', $1);
    return $decoded;
}

sub get_Folders {
    my $c = shift;
    my $folders_hashref = $c->listfolders();
    # Convert hashref to arrayref of arrayrefs for Mojolicious select
    my @options = map { [ $_, $folders_hashref->{$_} ] } sort keys %$folders_hashref;
    return \@options;
}

sub listfolders
{
	my $c = shift;
	use File::Find::Rule;
	my $PanelUser = $c->get_panel_user();
	my $root="/home/e-smith/files/users/$PanelUser/Maildir";
	$root="/home/e-smith/Maildir"  if  "$PanelUser" eq "admin" ;
	my @dirs = File::Find::Rule->new
	    ->extras({ untaint => 1 , untaint_pattern => qr|^([-+@\w&. /]+)$| })
	    ->directory
	    ->maxdepth(1)
	    ->in($root);
	my %out_dir;
	$out_dir{"INBOX"} .= "INBOX";
	$out_dir{""} .= "";
	for (sort @dirs) {
	       s/$root\/?\.?//;
	       my @exclu =("cur", "tmp", "new" , "INBOX" );
	       next if $_  ~~ @exclu;
	       $out_dir{$_} .= GetDisplayName(join('/',split('\.', $_)));
       	}
	return \%out_dir;
}


